sys_script_include.script:
var DashboardAPI = Class.create();
DashboardAPI.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getDashboardStats: function () {

        var response = {};

        // Total Users
        var userGA = new GlideAggregate('sys_user');
        userGA.addAggregate('COUNT');
        userGA.query();

        if (userGA.next()) {
            response.users = userGA.getAggregate('COUNT');
        } else {
            response.users = "0";
        }

        // Total Roles
        var roleGA = new GlideAggregate('sys_user_role');
        roleGA.addAggregate('COUNT');
        roleGA.query();

        if (roleGA.next()) {
            response.roles = roleGA.getAggregate('COUNT');
        } else {
            response.roles = "0";
        }

        // Total Departments
        var deptGA = new GlideAggregate('cmn_department');
        deptGA.addAggregate('COUNT');
        deptGA.query();

        if (deptGA.next()) {
            response.departments = deptGA.getAggregate('COUNT');
        } else {
            response.departments = "0";
        }

        return JSON.stringify(response);
    },

    type: 'DashboardAPI'
});
